import React, { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import { useCart } from "./CartContext";

const API_URL = "http://localhost:5001/api/products";
const BRAND_API_URL = "http://localhost:5001/api/brand";

const Header = ({ onCartClick, dark, setDark }) => {
  const { cart } = useCart();
  const totalQty = cart.reduce((sum, item) => sum + item.qty, 0);
  const location = useLocation();
  const [products, setProducts] = useState([]);
  const [brand, setBrand] = useState({ brandName: "Online Shop", logo: "" });

  useEffect(() => {
    fetch(API_URL)
      .then((res) => res.json())
      .then(setProducts)
      .catch(() => setProducts([]));
  }, []);

  useEffect(() => {
    fetch(BRAND_API_URL)
      .then((res) => res.json())
      .then(setBrand)
      .catch(() => setBrand({ brandName: "Online Shop", logo: "" }));
  }, []);

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 bg-white dark:bg-gray-900 shadow-md`}>
      <div className="container mx-auto flex items-center justify-between px-4 py-3">
        <Link to="/" className="flex items-center gap-2 font-bold text-xl text-blue-700 dark:text-blue-200 hover:text-blue-900">
          {brand.logo && (
            <img src={brand.logo} alt="Logo" className="h-10 w-10 object-contain rounded bg-gray-100 border" />
          )}
          <span>{brand.brandName}</span>
        </Link>
        <nav className="flex items-center gap-6">
          <Link to="/" className={`hover:text-blue-600 transition ${location.pathname === "/" ? "font-bold text-blue-600" : ""}`}>Home</Link>
          <Link to="/shop" className={`hover:text-blue-600 transition ${location.pathname.startsWith("/shop") ? "font-bold text-blue-600" : ""}`}>Shop</Link>
          <Link to="/contact" className={`hover:text-blue-600 transition ${location.pathname === "/contact" ? "font-bold text-blue-600" : ""}`}>Contact</Link>
          <Link to="/store" className={`hover:text-blue-600 transition ${location.pathname === "/store" ? "font-bold text-blue-600" : ""}`}>Store</Link>
          <Link to="/about" className={`hover:text-blue-600 transition ${location.pathname === "/about" ? "font-bold text-blue-600" : ""}`}>About</Link>
          {/* Cart Icon */}
          <button
            onClick={onCartClick}
            className="relative focus:outline-none ml-2"
            aria-label="Buka keranjang"
          >
            <svg className="w-7 h-7 text-blue-600" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13l-1.35 2.7A2 2 0 008.48 19h6.96a2 2 0 001.83-1.3L17 13M7 13V6a1 1 0 011-1h8a1 1 0 011 1v7" />
            </svg>
            {totalQty > 0 && (
              <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full px-2 text-xs font-bold">
                {totalQty}
              </span>
            )}
          </button>
          <button
            onClick={() => setDark((d) => !d)}
            className="ml-4 px-3 py-2 rounded bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-100 shadow hover:bg-gray-300 dark:hover:bg-gray-600 font-bold text-sm"
            aria-label="Toggle dark mode"
          >
            {dark ? "☀️ Light" : "🌙 Dark"}
          </button>
        </nav>
      </div>
    </header>
  );
};

export default Header;
